"use client";

import { useState, useEffect } from "react";
import { useCart } from "@/app/store/cart";
import { X, Plus, Minus, Leaf, Flame, Info } from "lucide-react";

interface FoodItemModalProps {
  item: any;
  onClose: () => void;
  onAddToCart: () => void;
}

export default function FoodItemModal({ item, onClose, onAddToCart }: FoodItemModalProps) {
  const addItem = useCart((s) => s.addItem);
  const [qty, setQty] = useState(1);
  const [size, setSize] = useState(item.sizes?.[0]);
  const [isAdding, setIsAdding] = useState(false);

  const total = size.price * qty;
  const hasMultipleSizes = item.sizes?.length > 1;

  // Prevent body scroll when modal is open
  useEffect(() => {
    document.body.style.overflow = 'hidden';
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, []);

  const handleAddToCart = () => {
    setIsAdding(true);
    
    addItem({
      productId: item.id,
      name: item.name,
      sizeLabel: size.size_label,
      price: size.price,
      qty,
      veg: item.veg,
    });
    
    onAddToCart();
    
    setTimeout(() => {
      setIsAdding(false);
      onClose();
    }, 300);
  };

  return (
    // This modal will render at the root level, not inside the RestaurantPage
    <div className="fixed inset-0 z-[9999]">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-black/60 backdrop-blur-sm"
        onClick={onClose}
      />

      {/* Bottom Sheet Modal */}
      <div 
        className="absolute bottom-0 left-0 right-0 bg-white rounded-t-3xl shadow-2xl max-h-[90vh] overflow-hidden animate-slide-up"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Drag handle */}
        <div className="pt-4 flex justify-center cursor-grab active:cursor-grabbing">
          <div className="w-12 h-1.5 bg-gray-300 rounded-full" />
        </div>

        {/* Close button at top */}
        <button
          onClick={onClose}
          className="absolute top-4 right-4 p-2 hover:bg-gray-100 rounded-full transition-colors z-20"
          aria-label="Close"
        >
          <X className="w-5 h-5 text-gray-500" />
        </button>

        {/* Header */}
        <div className="p-6 pb-4">
          <div className="flex items-center gap-2 mb-2">
            <div className={`p-1.5 rounded-lg ${item.veg ? 'bg-emerald-50' : 'bg-rose-50'}`}>
              {item.veg ? (
                <Leaf className="w-4 h-4 text-emerald-600" />
              ) : (
                <Flame className="w-4 h-4 text-rose-600" />
              )}
            </div>
            <span className={`text-sm font-medium ${item.veg ? 'text-emerald-700' : 'text-rose-700'}`}>
              {item.veg ? 'Vegetarian' : 'Non-Vegetarian'}
            </span>
          </div>
          <h2 className="text-2xl font-bold text-gray-900">{item.name}</h2>
          {item.category_name && (
            <p className="text-sm text-gray-500 mt-1">{item.category_name}</p>
          )}
        </div>

        {/* Scrollable content */}
        <div className="overflow-y-auto px-6" style={{ maxHeight: 'calc(90vh - 250px)' }}>
          {/* Image */}
          {item.images?.[0] && (
            <div className="mb-6">
              <div className="relative w-full h-56 rounded-2xl overflow-hidden shadow-lg">
                <img
                  src={item.images[0].image_url}
                  alt={item.name}
                  className="w-full h-full object-cover"
                />
                <div className="absolute bottom-4 right-4 bg-white/90 backdrop-blur-sm px-3 py-1.5 rounded-full">
                  <span className="text-sm font-semibold text-gray-900">
                    ₹{size.price}
                  </span>
                </div>
              </div>
            </div>
          )}

          {/* Description */}
          {item.description && (
            <div className="mb-6">
              <div className="flex items-center gap-2 mb-3">
                <Info className="w-5 h-5 text-gray-400" />
                <h3 className="font-semibold text-gray-900">Description</h3>
              </div>
              <p className="text-gray-600 leading-relaxed bg-gray-50 p-4 rounded-xl border border-gray-100">
                {item.description}
              </p>
            </div>
          )}

          {/* Size Selector */}
          {hasMultipleSizes && (
            <div className="mb-6">
              <h3 className="font-semibold text-gray-900 mb-3">Choose Size</h3>
              <div className="grid grid-cols-2 gap-3">
                {item.sizes.map((s: any) => (
                  <button
                    key={s.id}
                    onClick={() => setSize(s)}
                    className={`p-4 rounded-xl border-2 transition-all relative ${
                      size.id === s.id
                        ? 'border-emerald-500 bg-emerald-50 shadow-sm'
                        : 'border-gray-200 hover:border-gray-300 bg-white'
                    }`}
                  >
                    <div className="text-left">
                      <p className="font-semibold text-gray-900">{s.size_label}</p>
                      <p className="text-sm text-gray-600 mt-1">Serves 1 person</p>
                      <p className="text-lg font-bold text-emerald-600 mt-2">
                        ₹{s.price}
                      </p>
                    </div>
                    {size.id === s.id && (
                      <div className="w-6 h-6 bg-emerald-500 rounded-full flex items-center justify-center absolute -top-2 -right-2">
                        <div className="w-2 h-2 bg-white rounded-full" />
                      </div>
                    )}
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Quantity Selector */}
          <div className="mb-8">
            <h3 className="font-semibold text-gray-900 mb-3">Quantity</h3>
            <div className="flex items-center justify-between bg-gray-50 p-4 rounded-2xl border border-gray-100">
              <div>
                <p className="font-semibold text-gray-900">₹{total}</p>
                <p className="text-sm text-gray-500">Total price</p>
              </div>
              <div className="flex items-center gap-4">
                <button
                  onClick={() => setQty(Math.max(1, qty - 1))}
                  className={`w-10 h-10 rounded-full flex items-center justify-center ${
                    qty > 1
                      ? 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                      : 'bg-gray-100 text-gray-400 cursor-not-allowed'
                  } transition-colors`}
                  disabled={qty <= 1}
                >
                  <Minus className="w-4 h-4" />
                </button>
                
                <div className="flex flex-col items-center">
                  <span className="text-2xl font-bold text-gray-900 w-8 text-center">
                    {qty}
                  </span>
                  <span className="text-xs text-gray-500 mt-1">items</span>
                </div>
                
                <button
                  onClick={() => setQty(qty + 1)}
                  className="w-10 h-10 rounded-full bg-emerald-50 text-emerald-700 flex items-center justify-center hover:bg-emerald-100 transition-colors"
                >
                  <Plus className="w-4 h-4" />
                </button>
              </div>
            </div>
          </div>
        </div>

        {/* Add to Cart Footer */}
        <div className="border-t border-gray-100 p-6">
          <button
            onClick={handleAddToCart}
            disabled={isAdding}
            className={`w-full py-4 rounded-xl font-semibold text-lg transition-all flex items-center justify-center gap-3 ${
              isAdding
                ? 'bg-emerald-400 cursor-wait'
                : 'bg-gradient-to-r from-emerald-500 to-emerald-600 hover:from-emerald-600 hover:to-emerald-700 active:scale-[0.98] shadow-lg shadow-emerald-500/25'
            }`}
          >
            {isAdding ? (
              <>
                <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin" />
                <span>Adding to Cart...</span>
              </>
            ) : (
              <>
                <Plus className="w-5 h-5" />
                <span>Add to Cart</span>
                <span className="ml-auto">₹{total}</span>
              </>
            )}
          </button>
          
          <p className="text-center text-xs text-gray-500 mt-3">
            You can modify quantities later in your cart
          </p>
        </div>
      </div>
    </div>
  );
}